//! The editor's HTML data (`data/html.data`, generated by `cargo xtask web-data` from MDN's
//! public-domain data): the elements and their attributes (global ones under `*`), and
//! whether each is deprecated, experimental or non-standard. Embedded; parsed on first use.

use std::collections::HashMap;

static DATA: &str = include_str!("../data/html.data");

#[derive(Debug, Default)]
pub struct Html {
    /// (tag, flags), in name order.
    pub elements: Vec<(&'static str, &'static str)>,
    /// Tag (`*`: global) → (attribute, flags).
    attributes: HashMap<&'static str, Vec<(&'static str, &'static str)>>,
    /// (tag, attribute) → the values it takes (e.g. `input` / `type` → `button`, `email`…).
    values: HashMap<(&'static str, &'static str), Vec<&'static str>>,
}

impl Html {
    /// The heap it takes (its text is the binary's: only the tables).
    pub fn weight(&self) -> u64 {
        use kernel::memory::{map_bytes, vec_bytes};
        vec_bytes(&self.elements)
            + map_bytes(&self.attributes)
            + self.attributes.values().map(vec_bytes).sum::<u64>()
            + map_bytes(&self.values)
            + self.values.values().map(vec_bytes).sum::<u64>()
    }
}

/// The data: read on first use, let go when unused for a while (the module's
/// `release_idle`), read again when needed.
pub static HTML: kernel::cache::OnDemand<Html> = kernel::cache::OnDemand::new(load);

pub fn get() -> std::sync::Arc<Html> {
    HTML.get()
}

fn load() -> Html {
    let mut html = Html::default();
    for line in DATA.lines().filter(|l| !l.starts_with('#')) {
        let mut f = line.split('\t');
        match (f.next(), f.next(), f.next(), f.next()) {
            (Some("e"), Some(tag), Some(flags), _) => html.elements.push((tag, flags)),
            (Some("a"), Some(tag), Some(name), flags) => {
                html.attributes.entry(tag).or_default().push((name, flags.unwrap_or("")));
            }
            (Some("v"), Some(tag), Some(attribute), Some(value)) => {
                html.values.entry((tag, attribute)).or_default().push(value);
            }
            _ => {}
        }
    }
    html
}

impl Html {
    /// The attributes specific to `tag`.
    pub fn attributes(&self, tag: &str) -> &[(&'static str, &'static str)] {
        self.attributes.get(tag).map_or(&[], Vec::as_slice)
    }

    /// The values attribute `attribute` of `tag` takes, if listed.
    pub fn values(&self, tag: &str, attribute: &str) -> &[&'static str] {
        self.values
            .iter()
            .find(|((t, a), _)| *t == tag && *a == attribute)
            .map_or(&[], |(_, v)| v.as_slice())
    }

    /// The global attributes (`class`, `id`…).
    /// Element `tag` (lowercase) is deprecated.
    pub fn element_deprecated(&self, tag: &str) -> bool {
        self.elements.iter().any(|(t, f)| *t == tag && f.contains('d'))
    }

    /// Attribute `name` of element `tag` (or a global one) is deprecated.
    pub fn attribute_deprecated(&self, tag: &str, name: &str) -> bool {
        let flags = self
            .attributes(tag)
            .iter()
            .chain(self.global_attributes())
            .find(|(a, _)| *a == name)
            .map(|(_, f)| *f);
        flags.is_some_and(|f| f.contains('d'))
    }

    pub fn global_attributes(&self) -> &[(&'static str, &'static str)] {
        self.attributes("*")
    }
}

